import * as React from "react";
import { FileTextIcon } from "@phosphor-icons/react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { useIsMobile } from "@/hooks/use-mobile";
import { MessageMarkdown } from "./message-markdown";
import type { ChatWorkspaceFile } from "./types";

// Extension -> fence language tag, so Shiki (via the `code` plugin wired into
// MessageMarkdown) highlights it the same way a fenced code block in chat
// would. Falls back to the bare extension for anything not listed here —
// Shiki accepts most language ids directly (e.g. "py", "go", "rs").
const EXTENSION_LANGUAGE_MAP: Record<string, string> = {
  js: "javascript",
  jsx: "jsx",
  ts: "typescript",
  tsx: "tsx",
  mjs: "javascript",
  cjs: "javascript",
  py: "python",
  rb: "ruby",
  sh: "bash",
  yml: "yaml",
  md: "markdown",
};

function getExtension(path: string | undefined): string {
  if (!path) return "";
  const match = /\.([a-zA-Z0-9]+)$/.exec(path);
  return match ? match[1].toLowerCase() : "";
}

function fence(content: string, language: string): string {
  return "```" + language + "\n" + content + "\n```";
}

/**
 * Shown when the agent calls present_file — the file's live content.
 * Markdown files get a Preview/Code toggle (rendered as real markdown, or as
 * syntax-highlighted literal source); every other extension is shown as a
 * single syntax-highlighted block, both routed through the same
 * MessageMarkdown/Shiki pipeline used for chat messages rather than a
 * separate renderer.
 */
function WorkspaceFilePanel({
  file,
  onOpenChange,
}: {
  file: ChatWorkspaceFile | null;
  onOpenChange: (open: boolean) => void;
}) {
  const extension = getExtension(file?.path);
  const isMarkdown = extension === "md" || extension === "mdx";
  const content = file?.content ?? "";
  const language = EXTENSION_LANGUAGE_MAP[extension] ?? extension ?? "text";
  const isMobile = useIsMobile();

  const titleRow = (
    <SheetTitle className="flex min-w-0 items-center gap-2">
      <FileTextIcon className="size-4 shrink-0 text-muted-foreground" />
      <span className="truncate">{file?.title ?? file?.path}</span>
    </SheetTitle>
  );

  return (
    <Sheet open={!!file} onOpenChange={onOpenChange}>
      <SheetContent
        side={isMobile ? "bottom" : "right"}
        className="w-full sm:max-w-lg data-[side=bottom]:min-h-[60%] data-[side=bottom]:max-h-[85vh]"
      >
        {!file ? (
          <>
            <SheetHeader className="border-b border-border">{titleRow}</SheetHeader>
            <div className="flex flex-1 flex-col overflow-y-auto px-4 py-4">
              <p className="text-xs text-muted-foreground">Loading…</p>
            </div>
          </>
        ) : isMarkdown ? (
          <Tabs defaultValue="preview" className="flex flex-1 flex-col gap-0">
            <SheetHeader className="flex-row items-center justify-between gap-3 border-b border-border">
              {titleRow}
              <TabsList className="mr-8 shrink-0">
                <TabsTrigger value="preview">Preview</TabsTrigger>
                <TabsTrigger value="code">Code</TabsTrigger>
              </TabsList>
            </SheetHeader>
            {file.description && (
              <SheetDescription className="px-4">{file.description}</SheetDescription>
            )}
            <div className="flex-1 overflow-y-auto px-4 py-4">
              <TabsContent value="preview">
                <MessageMarkdown content={content} />
              </TabsContent>
              <TabsContent value="code">
                <MessageMarkdown content={fence(content, "markdown")} />
              </TabsContent>
            </div>
          </Tabs>
        ) : (
          <>
            <SheetHeader className="border-b border-border">
              {titleRow}
              {file.description && <SheetDescription>{file.description}</SheetDescription>}
            </SheetHeader>
            <div className="flex-1 overflow-y-auto px-4 py-4">
              <MessageMarkdown content={fence(content, language)} />
            </div>
          </>
        )}
      </SheetContent>
    </Sheet>
  );
}

export { WorkspaceFilePanel };

"use client";

import * as React from "react";
import {
  Questionnaire,
  QuestionnaireItem,
  QuestionnaireTitle,
  QuestionnaireChoices,
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireInput,
  QuestionnaireActions,
  QuestionnaireProgress,
  QuestionnairePrevious,
  QuestionnaireSkip,
  QuestionnaireNext,
  QuestionnaireSubmit,
} from "@/components/ui/questionnaire";
import { Button } from "@/components/ui/button";
import { CheckIcon, XIcon } from "@phosphor-icons/react";
import { ToolCallCard } from "./tool-call-card";
import type { ChatInterruptData } from "./types";

/**
 * HITL approval + multi-step clarification — built on the Questionnaire
 * primitive, which already is a multi-step Q&A wizard (progress, keyboard
 * 1-9 shortcuts via shortcuts="numbers", previous/skip/next/submit nav).
 * NotebookChat.js hand-rolled all of this (step state, keyboard handler,
 * custom-text fallback); here it's what the primitive is built for.
 */
function InterruptPanel({
  interrupt,
  onSubmitClarification,
  onDecideHitl,
}: {
  interrupt: ChatInterruptData;
  onSubmitClarification?: (answers: Record<string, string>) => void;
  onDecideHitl?: (actionId: string, decision: "approve" | "reject") => void;
}) {
  if (interrupt.kind === "hitl") {
    return (
      <div className="flex flex-col gap-2 rounded-none border border-border bg-card p-3">
        <div className="text-xs font-semibold text-muted-foreground">
          Waiting for your approval to continue
        </div>
        {interrupt.actionRequests.map((action) => (
          <div key={action.id} className="flex flex-col gap-2">
            {/* Same ToolCallCard every completed call renders through —
                starts collapsed like any other tool card. The header alone
                (title + subtitle, e.g. "Creating agent" / "Exam Master")
                already tells a human enough to decide approve/reject; forcing
                it open by default made a large upsert_agent payload (a long
                system prompt, etc.) grow tall enough to push the
                Approve/Reject buttons off-screen. Still capped + scrollable
                for whenever it IS expanded. */}
            <div className="max-h-[50vh] overflow-y-auto">
              <ToolCallCard
                toolCall={{
                  id: action.id,
                  name: action.toolName,
                  args: action.args,
                  status: "running",
                }}
                // Explicit `false`, not omitted — ToolCallCard's own default
                // for an upsert defaults to open while pending (status here
                // is always "running"), which is exactly the forced-open
                // behavior this panel doesn't want.
                defaultOpen={false}
              />
            </div>
            <div className="flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                aria-label={`Reject ${action.label}`}
                onClick={() => onDecideHitl?.(action.id, "reject")}
              >
                <XIcon /> Reject
              </Button>
              <Button
                type="button"
                size="sm"
                aria-label={`Approve ${action.label}`}
                onClick={() => onDecideHitl?.(action.id, "approve")}
              >
                <CheckIcon /> Approve
              </Button>
            </div>
          </div>
        ))}
      </div>
    );
  }

  const { questions } = interrupt;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const answers: Record<string, string> = {};
    questions.forEach((q, idx) => {
      const name = q.id ?? `q-${idx}`;
      const value = data.get(name);
      if (typeof value === "string" && value.trim()) answers[name] = value.trim();
    });
    onSubmitClarification?.(answers);
  };

  return (
    <div className="rounded-none border border-border bg-card p-3">
      <Questionnaire
        items={questions.map((q, idx) => ({
          name: q.id ?? `q-${idx}`,
          choices: q.options?.map((o) => ({ value: o.value })),
          required: q.required !== false,
        }))}
        shortcuts="numbers"
        onSubmit={handleSubmit}
      >
        {questions.map((q, idx) => {
          const name = q.id ?? `q-${idx}`;
          return (
            <QuestionnaireItem key={name} name={name} required={q.required !== false}>
              <QuestionnaireTitle>{q.question}</QuestionnaireTitle>
              {q.options?.length ? (
                <QuestionnaireChoices>
                  {q.options.map((opt) => (
                    <QuestionnaireChoice key={opt.value} value={opt.value}>
                      {opt.label}
                      {opt.description && (
                        <QuestionnaireChoiceDescription>
                          {opt.description}
                        </QuestionnaireChoiceDescription>
                      )}
                    </QuestionnaireChoice>
                  ))}
                  {q.allowCustom && (
                    <QuestionnaireInput placeholder="Something else…" />
                  )}
                </QuestionnaireChoices>
              ) : (
                <QuestionnaireInput placeholder="Type your answer…" />
              )}
            </QuestionnaireItem>
          );
        })}
        <QuestionnaireActions>
          <QuestionnaireProgress />
          <QuestionnairePrevious />
          <QuestionnaireSkip />
          <QuestionnaireNext />
          <QuestionnaireSubmit />
        </QuestionnaireActions>
      </Questionnaire>
    </div>
  );
}

export { InterruptPanel };

